--
-- Table structure for table `users`
--

DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `role` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'reader',
  `job_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bio` text COLLATE utf8mb4_unicode_ci,
  `avatar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `last_login_at` timestamp NULL DEFAULT NULL,
  `disabled_at` timestamp NULL DEFAULT NULL,
  `blocked_reason` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `blocked_note` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `password_reset_required_at` timestamp NULL DEFAULT NULL,
  `moderation_review_requested_at` timestamp NULL DEFAULT NULL,
  `moderation_review_reason` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `moderation_review_note` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `moderation_review_requested_by_id` bigint unsigned DEFAULT NULL,
  `moderation_review_comment_id` bigint unsigned DEFAULT NULL,
  `moderation_review_comment_excerpt` text COLLATE utf8mb4_unicode_ci,
  `moderation_review_article_title` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `moderation_review_resolved_at` timestamp NULL DEFAULT NULL,
  `moderation_review_resolution` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `moderation_review_resolved_by_id` bigint unsigned DEFAULT NULL,
  `remember_token` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`),
  KEY `users_role_index` (`role`),
  KEY `users_is_active_index` (`is_active`),
  KEY `users_last_login_at_index` (`last_login_at`),
  KEY `users_moderation_review_requested_at_index` (`moderation_review_requested_at`),
  KEY `users_moderation_review_requested_by_id_foreign` (`moderation_review_requested_by_id`),
  KEY `users_moderation_review_comment_id_foreign` (`moderation_review_comment_id`),
  KEY `users_moderation_review_resolved_by_id_foreign` (`moderation_review_resolved_by_id`),
  KEY `users_moderation_review_resolved_at_index` (`moderation_review_resolved_at`),
  CONSTRAINT `users_moderation_review_comment_id_foreign` FOREIGN KEY (`moderation_review_comment_id`) REFERENCES `comments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `users_moderation_review_requested_by_id_foreign` FOREIGN KEY (`moderation_review_requested_by_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `users_moderation_review_resolved_by_id_foreign` FOREIGN KEY (`moderation_review_resolved_by_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2507 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
